function justifyText(words: string[], width: number): string[] {
  const lines: string[] = [];
  let i = 0;
  while (i < words.length) {
    let j = i, letters = 0;
    // with j − i words on the line, one more word needs j − i spaces before it
    while (j < words.length && letters + words[j].length + (j - i) <= width) {
      letters += words[j].length;
      j++;
    }
    const gaps = j - i - 1;
    let line = "";
    if (j === words.length || gaps === 0) {
      line = words.slice(i, j).join(" ");
      line += " ".repeat(width - line.length);
    } else {
      const spare = width - letters;
      const base = Math.floor(spare / gaps), extra = spare % gaps;
      for (let k = i; k < j - 1; k++) {
        line += words[k] + " ".repeat(base + (k - i < extra ? 1 : 0));
      }
      line += words[j - 1];
    }
    lines.push(line);
    i = j;
  }
  return lines;
}

